import AppKit
import SwiftUI

/// Official brand marks (Simple Icons, CC0: simpleicons.org; Outlook and Yahoo from v9, before they were removed), drawn in each brand's color.
/// Single-path 24×24 SVGs, kept inline so the app needs no resource bundle.
struct BrandLogo: View {
    let brand: String   // gmail, icloud, yahoo, google, microsoft, claude, codex, gemini; carriers ups, fedex, usps, amazon, dhl
    var size: CGFloat = 20
    var body: some View {
        if let (svg, color) = Self.logos[brand], let img = NSImage(data: Data(svg.utf8)) {
            Image(nsImage: { img.isTemplate = true; return img }()).resizable().scaledToFit()
                .foregroundStyle(color).frame(width: size, height: size).accessibilityHidden(true)
        }
